	private static FunctionEvaluator caseFold(boolean lower) {
		return args -> {
			LmdbNativeValueCodec.DecodedValue decoded = args[0];
			if (decoded.error() || !decoded.stringLiteral()) {
				return LmdbNativeValueCodec.DecodedValue.ERROR;
			}
			// the generic LCASE/UCASE keep the input's kind: language tag and base direction survive;
			// default-locale casing mirrors the generic functions exactly
			String label = lower ? decoded.label().toLowerCase() : decoded.label().toUpperCase();
			return LmdbNativeValueCodec.DecodedValue.literal(label, decoded.language().orElse(null),
					decoded.datatypeIri(), decoded.coreDatatype(), decoded.baseDirection());
		};
	}

	/**
	 * Builds a delegating evaluator around the exact generic {@link Function} implementation. A decoded ERROR argument
	 * short-circuits (the generic engine never reaches the function when an argument evaluation errors), a
	 * {@link ValueExprEvaluationException} maps to ERROR (SPARQL type error), and any other runtime exception
	 * propagates exactly as it would in the generic engine.
	 */
	static FunctionEvaluator delegating(Function function) {
		return args -> {
			Value[] values = new Value[args.length];
			for (int i = 0; i < args.length; i++) {
				Value value = LmdbNativeValueCodec.toValue(args[i]);
				if (value == null) {
					return LmdbNativeValueCodec.DecodedValue.ERROR;
				}
				values[i] = value;
			}
			try {
				Value result = function.evaluate(SimpleValueFactory.getInstance(), values);
				return result == null ? LmdbNativeValueCodec.DecodedValue.ERROR
						: LmdbNativeValueCodec.fromValue(result);
			} catch (ValueExprEvaluationException e) {
				return LmdbNativeValueCodec.DecodedValue.ERROR;
			}
		};
	}

	private enum DateField {
		YEAR,
		MONTH,
		DAY,
		HOURS,
		MINUTES,
		SECONDS,
		TIMEZONE,
		TZ
	}

	private static final int NO_FRACTION = 0x3FF;
	private static final int NO_TIMEZONE_BITS = 0x7F;

	/**
	 * Inline-id bit-math fast path for one date-part field. Only decides cases the bit layout fully determines with the
	 * exact generic result; everything else (store-record dates, gYear/time/... datatypes, undefined fields on T_DATE)
	 * returns {@code null} so the caller falls through to the normative evaluator.
	 */
	private static InlineFastPath datePart(DateField field) {
		return id -> {
			if (!ValueIds.isInlined(id)) {
				return null;
			}
			int type = ValueIds.getIdType(id);
			boolean hasTime;
			if (type == ValueIds.T_DATETIME || type == ValueIds.T_DATETIMESTAMP) {
				hasTime = true;
			} else if (type == ValueIds.T_DATE) {
				hasTime = false;
			} else {
				return null;
			}
			long bits = ValueIds.getValue(id);
			switch (field) {
			case YEAR:
				return integerResult(bits & 0x1FFF);
			case MONTH:
				return integerResult((bits >>> 13) & 0x0F);
			case DAY:
				return integerResult((bits >>> 17) & 0x1F);
			case HOURS:
				return hasTime ? integerResult((bits >>> 22) & 0x1F) : null;
			case MINUTES:
				return hasTime ? integerResult((bits >>> 27) & 0x3F) : null;
			case SECONDS: {
				if (!hasTime) {
					return null;
				}
				long second = (bits >>> 33) & 0x3F;
				int milli = (int) ((bits >>> 39) & 0x3FF);
				// mirrors the generic Seconds function exactly: no fraction -> integer-form label, else the
				// double sum's String form; both are xsd:decimal
				String label = milli == NO_FRACTION ? String.valueOf(second)
						: String.valueOf(milli / 1000.0 + second);
				return LmdbNativeValueCodec.DecodedValue.literal(label, null,
						CoreDatatype.XSD.DECIMAL.getIri().stringValue(), CoreDatatype.XSD.DECIMAL);
			}
			case TIMEZONE: {
				int tzBits = (int) ((bits >>> 49) & 0x7F);
				if (tzBits == NO_TIMEZONE_BITS) {
					return LmdbNativeValueCodec.DecodedValue.ERROR;
				}
				int offsetMinutes = (tzBits - 64) * 15;
				int minutes = Math.abs(offsetMinutes);
				int hours = minutes / 60;
				minutes = minutes - hours * 60;
				StringBuilder tzDuration = new StringBuilder();
				if (offsetMinutes < 0) {
					tzDuration.append('-');
				}
				tzDuration.append("PT");
				if (hours > 0) {
					tzDuration.append(hours).append('H');
				}
				if (minutes > 0) {
					tzDuration.append(minutes).append('M');
				}
				if (offsetMinutes == 0) {
					tzDuration.append("0S");
				}
				return LmdbNativeValueCodec.DecodedValue.literal(tzDuration.toString(), null,
						CoreDatatype.XSD.DAYTIMEDURATION.getIri().stringValue(), CoreDatatype.XSD.DAYTIMEDURATION);
			}
			case TZ: {
				int tzBits = (int) ((bits >>> 49) & 0x7F);
				String tz;
				if (tzBits == NO_TIMEZONE_BITS) {
					tz = "";
				} else {
					int offsetMinutes = (tzBits - 64) * 15;
					if (offsetMinutes == 0) {
						tz = "Z";
					} else {
						int minutes = Math.abs(offsetMinutes);
						tz = (offsetMinutes < 0 ? "-" : "+") + pad2(minutes / 60) + ":" + pad2(minutes % 60);
					}
				}
				return LmdbNativeValueCodec.DecodedValue.literal(tz, null,
						CoreDatatype.XSD.STRING.getIri().stringValue(), CoreDatatype.XSD.STRING);
			}
			}
			return null;
		};
	}

	private static String pad2(int value) {
		return value < 10 ? "0" + value : Integer.toString(value);
	}

	private static LmdbNativeValueCodec.DecodedValue integerResult(long value) {
		return LmdbNativeValueCodec.DecodedValue.decimal(Long.toString(value),
				java.math.BigDecimal.valueOf(value), CoreDatatype.XSD.INTEGER);
	}

